package com.jianghu.offline;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;

public class MainActivity extends Activity {
 static final int GROWTH=100; Game v;
 @Override public void onCreate(Bundle b){super.onCreate(b);v=new Game(this);setContentView(v);}
 @Override protected void onPause(){super.onPause();v.save();}
 class Game extends View{
  Paint p=new Paint(3); SharedPreferences s; int tab=0,lv=1,exp=0,hp=12000,maxHp=12000,atk=2000,def=800,stamina=100,energy=100; long silver=1000,jade=20; int floor=1,skill=1,gear=1,crit=5,kills=0; long lastSave,lastTick,lastAuto; boolean autoBattle=false; int enemyMaxHp=5000,enemyHp=5000; String battleLog="点击挑战开始战斗"; String[] tabs={"江湖","修炼","战斗","背包","人物"};
  Game(Context c){super(c);s=getSharedPreferences("jianghu",0);load();}
  void load(){lv=s.getInt("lv",1);exp=s.getInt("exp",0);hp=s.getInt("hp",12000);maxHp=s.getInt("max",12000);atk=s.getInt("atk",2000);def=s.getInt("def",800);stamina=s.getInt("sta",100);energy=s.getInt("ene",100);silver=s.getLong("silver",1000);jade=s.getLong("jade",20);floor=s.getInt("floor",1);skill=s.getInt("skill",1);gear=s.getInt("gear",1);crit=s.getInt("crit",5);kills=s.getInt("kills",0);lastSave=s.getLong("save",System.currentTimeMillis());lastTick=System.currentTimeMillis();offline();}
  void offline(){long now=System.currentTimeMillis(),mins=Math.min(480,Math.max(0,(now-lastSave)/60000));if(mins>0){silver+=mins*(5000+floor*500);exp+=(int)Math.min(Integer.MAX_VALUE,mins*20);energy=Math.min(100,energy+(int)Math.min(100,mins*2));level();}}
  void save(){s.edit().putInt("lv",lv).putInt("exp",exp).putInt("hp",hp).putInt("max",maxHp).putInt("atk",atk).putInt("def",def).putInt("sta",stamina).putInt("ene",energy).putLong("silver",silver).putLong("jade",jade).putInt("floor",floor).putInt("skill",skill).putInt("gear",gear).putInt("crit",crit).putInt("kills",kills).putLong("save",System.currentTimeMillis()).apply();}
  void level(){while(exp>=100){exp-=100;lv++;maxHp+=1500;hp=maxHp;atk+=400;def+=200;if(lv%5==0)jade++;}}
  void text(Canvas c,String t,float x,float y,float z,int color){p.setStyle(Paint.Style.FILL);p.setTextSize(z);p.setColor(color);c.drawText(t,x,y,p);} void box(Canvas c,float l,float t,float r,float b,int color){p.setColor(color);p.setStyle(Paint.Style.FILL);c.drawRoundRect(l,t,r,b,18,18,p);} void btn(Canvas c,String t,float l,float y,float r){box(c,l,y,r,y+55,Color.rgb(102,72,43));p.setTextAlign(Paint.Align.CENTER);text(c,t,(l+r)/2,y+35,17,Color.WHITE);p.setTextAlign(Paint.Align.LEFT);}
  protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();c.drawColor(Color.rgb(222,207,180));box(c,0,0,w,75,Color.rgb(48,36,28));text(c,"江湖·离线版",18,46,25,Color.WHITE);text(c,"Lv."+lv+"  银两 "+silver,w-190,35,14,Color.WHITE);text(c,"● 完全离线  成长 ×100",w-220,58,12,Color.WHITE);box(c,12,88,w-12,h-145,Color.rgb(247,239,220));if(tab==0)world(c,w);else if(tab==1)cult(c,w);else if(tab==2)battle(c,w,h);else if(tab==3)bag(c,w);else person(c,w);box(c,0,h-130,w,h,Color.rgb(43,33,26));for(int i=0;i<5;i++){if(i==tab)box(c,i*w/5,h-130,(i+1)*w/5,h-125,Color.rgb(190,145,65));text(c,tabs[i],i*w/5+w/10-16,h-75,15,Color.WHITE);}if(stamina<100)stamina++;if(energy<100)energy++;if(System.currentTimeMillis()-lastTick>30000){save();lastTick=System.currentTimeMillis();}if(tab==2&&autoBattle&&System.currentTimeMillis()-lastAuto>2500){if(stamina>=10)fight(1);lastAuto=System.currentTimeMillis();}postInvalidateDelayed(1000);}
  void world(Canvas c,float w){text(c,"青石镇",30,130,25,Color.rgb(70,45,25));text(c,"离线挂机与江湖探索",30,158,14,Color.DKGRAY);text(c,"当前副本：第 "+floor+" 层",30,190,16,Color.DKGRAY);text(c,"任务：击败山贼 "+kills+" 次",30,220,15,Color.DKGRAY);text(c,"离线收益：每分钟获得银两与修为",30,245,14,Color.DKGRAY);btn(c,"切换地图",30,275,w/2-10);btn(c,"杂货铺",w/2+10,275,w-30);btn(c,"每日签到",30,350,w-30);}
  void cult(Canvas c,float w){text(c,"修炼",30,130,25,Color.rgb(70,45,25));text(c,"经验 "+exp+" / 100",30,170,16,Color.DKGRAY);text(c,"武学等级："+skill+"    暴击："+crit+"%",30,205,15,Color.DKGRAY);btn(c,"修炼一次",30,245,w-30);btn(c,"升级武学",30,320,w-30);}
  void bar(Canvas c,float l,float t,float r,float b,float ratio,int fill){box(c,l,t,r,b,Color.rgb(213,202,183));box(c,l,t,l+Math.max(0,(r-l)*Math.max(0,Math.min(1,ratio))),b,fill);}
  void battle(Canvas c,float w,float h){float left=28,right=w-28,top=112,area=h-285;float cardBottom=top+area*.40f;box(c,left,top,right,cardBottom,Color.rgb(235,222,197));text(c,"历练 · 第 "+floor+" 层",left+18,top+34,22,Color.rgb(73,47,29));text(c,"山贼头目",left+18,top+70,19,Color.rgb(92,50,36));text(c,"敌方气血  "+enemyHp+" / "+enemyMaxHp,left+18,top+100,13,Color.DKGRAY);bar(c,left+18,top+112,right-18,top+124,enemyMaxHp<=0?0:(float)enemyHp/enemyMaxHp,Color.rgb(176,54,43));text(c,"玩家气血  "+hp+" / "+maxHp,left+18,top+151,13,Color.DKGRAY);bar(c,left+18,top+162,right-18,top+174,(float)hp/maxHp,Color.rgb(63,135,84));text(c,"攻击 "+atk+"   防御 "+def+"   暴击 "+crit+"%",left+18,top+200,13,Color.rgb(80,64,47));text(c,"体力 "+stamina+"   技能能量 "+energy+"/100",left+18,top+224,13,Color.rgb(80,64,47));float by=top+area*.46f;float bh=Math.max(48,Math.min(60,area*.105f));btn(c,autoBattle?"自动战斗：开启":"自动战斗：关闭",left,by,right);btn(c,"挑战一轮",left,by+bh+10,right);btn(c,"绝技 · 流云破",left,by+(bh+10)*2,right);btn(c,"连续挑战 ×10",left,by+(bh+10)*3,right);float logY=by+(bh+10)*4+8;if(logY<h-170){box(c,left,logY,right,Math.min(h-165,logY+55),Color.rgb(230,218,194));text(c,"战况："+battleLog,left+12,logY+32,13,Color.rgb(88,67,47));}}
  void bag(Canvas c,float w){text(c,"背包",30,130,25,Color.rgb(70,45,25));text(c,"青锋剑 · 品质 "+gear,35,175,17,Color.DKGRAY);text(c,"回春丹 ×999",35,215,17,Color.DKGRAY);text(c,"强化石 · 战斗掉落",35,255,15,Color.DKGRAY);btn(c,"使用回春丹",30,300,w-30);}
  void person(Canvas c,float w){text(c,"人物",30,130,25,Color.rgb(70,45,25));text(c,"等级："+lv,35,175,17,Color.DKGRAY);text(c,"气血："+hp+" / "+maxHp,35,210,17,Color.DKGRAY);text(c,"攻击："+atk,35,245,17,Color.DKGRAY);text(c,"防御："+def,35,280,17,Color.DKGRAY);text(c,"元宝："+jade+"  暴击："+crit+"%",35,315,17,Color.DKGRAY);btn(c,"强化装备",30,355,w-30);btn(c,"本地存档",30,430,w-30);}
  public boolean onTouchEvent(MotionEvent e){if(e.getAction()!=1)return true;float x=e.getX(),y=e.getY(),w=getWidth(),h=getHeight();if(y>h-135){tab=Math.min(4,(int)(x/(w/5)));invalidate();return true;}if(tab==1&&y>235&&y<315){exp+=1500;level();save();invalidate();return true;}if(tab==1&&y>315&&y<405){long cost=200*skill;if(silver>=cost){silver-=cost;skill++;atk+=500;def+=300;crit=Math.min(80,crit+2);save();}invalidate();return true;}if(tab==2){float top=112,area=h-285,by=top+area*.46f,bh=Math.max(48,Math.min(60,area*.105f));if(y>=by&&y<=by+bh){autoBattle=!autoBattle;lastAuto=System.currentTimeMillis();save();invalidate();return true;}if(y>=by+bh+10&&y<=by+2*bh+10){fight(1);return true;}if(y>=by+(bh+10)*2&&y<=by+(bh+10)*2+bh){ultimate();return true;}if(y>=by+(bh+10)*3&&y<=by+(bh+10)*3+bh){fight(10);return true;}}if(tab==3&&y>285){hp=Math.min(maxHp,hp+maxHp/2);save();invalidate();return true;}if(tab==4&&y>345&&y<420){long cost=300*(gear+1);if(silver>=cost){silver-=cost;gear++;atk+=800;def+=500;maxHp+=2000;hp=maxHp;save();}invalidate();return true;}if(tab==4&&y>420){saveDialog();return true;}return true;}
  void fight(int n){n=Math.min(n,Math.max(0,stamina/10));if(n<1){toast("体力不足");battleLog="体力不足，暂时无法挑战";invalidate();return;}stamina-=n*10;int defeated=0;for(int i=0;i<n;i++){int incoming=Math.max(1,14+lv*2+floor*2-def);hp-=incoming;if(hp<=0){hp=maxHp/2;battleLog="气血不足，调息后继续";break;}int dealt=Math.max(100,atk);if(Math.random()*100<crit)dealt*=2;enemyHp-=dealt;exp+=25;silver+=5000+floor*1000;kills++;defeated++;if(enemyHp<=0){floor++;enemyMaxHp=5000+floor*1800;enemyHp=enemyMaxHp;battleLog="击败敌人！进入第 "+floor+" 层";if(Math.random()<.15)gear=Math.min(5,gear+1);}else{battleLog="造成 "+dealt+" 点伤害，受到 "+incoming+" 点伤害";}level();}if(defeated>0&&enemyHp>0)battleLog="造成伤害，敌方剩余气血 "+enemyHp;save();invalidate();}
  void ultimate(){if(energy<30){toast("技能能量不足");return;}energy-=30;int dealt=Math.max(300,atk*3);enemyHp-=dealt;exp+=150;silver+=200;crit=Math.min(80,crit+1);if(enemyHp<=0){floor++;enemyMaxHp=5000+floor*1800;enemyHp=enemyMaxHp;battleLog="绝技造成 "+dealt+" 伤害并击败敌人！";}else battleLog="流云破造成 "+dealt+" 点伤害";level();save();invalidate();}
  void saveDialog(){new AlertDialog.Builder(MainActivity.this).setTitle("本地存档").setMessage("数据只保存在本机。\n等级："+lv+"\n银两："+silver).setPositiveButton("保存",(d,w)->save()).setNegativeButton("关闭",null).show();} void toast(String s){android.widget.Toast.makeText(MainActivity.this,s,android.widget.Toast.LENGTH_SHORT).show();}
 }
}